GRAMMAR_TOPICS=[_g(*x) for x in [["pronouns","Personal pronouns","Use saya, awak, anda, dia and kami/kita.",["Saya pelajar.","Dia kawan saya."]],["nominal","Nominal sentences","Form identity statements without a present copula.",["Saya guru.","Ini rumah saya."]],["negation","Negation","Use bukan and tidak in common negative patterns.",["Ini bukan buku.","Saya tidak sibuk."]],["questions","Questions","Use apa, siapa, di mana, bila and bagaimana.",["Ini apa?","Di mana stesen?"]],["ber-verbs","ber- verbs","Recognize common activity verbs.",["Saya bekerja di pejabat.","Dia berjalan."]],["location","Location","Use di for simple locations.",["Saya di rumah.","Buku di atas meja."]],["possessive","Possession","Express ownership with common noun + pronoun patterns.",["Ini buku saya.","Itu kawan dia."]],["requests","Polite requests","Use sila and tolong in practical contexts.",["Tolong ulangi.","Sila duduk."]]]]
